using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;

public class CPHInline
{
    public bool Execute()
    {
        string executorName = args["userName"].ToString();
        bool isModerator = bool.Parse(args["isModerator"].ToString());
        bool isBroadcaster = bool.Parse(args["isBroadcaster"].ToString());

        // Check permissions
        if (!isModerator && !isBroadcaster) {
            CPH.SendMessage($"@{executorName}, this command is only available to moderators.");
            return false;
        }

        // Load user data
        string dataPath = @"C:\StreamerBot\UserData\eggs.json";

        if (!File.Exists(dataPath)) {
            CPH.SendMessage($"@{executorName}, no egg data found.");
            return false;
        }

        string jsonData = File.ReadAllText(dataPath);
        JObject data = JObject.Parse(jsonData);

        if (data["users"] == null || !data["users"].HasValues) {
            CPH.SendMessage($"@{executorName}, no user data available.");
            return false;
        }

        // Calculate statistics
        int totalUsers = 0;
        int totalEggs = 0;
        int totalD20Tokens = 0;
        int totalRRTokens = 0;
        int maxEggs = 0;
        int minEggs = int.MaxValue;

        foreach (var user in data["users"]) {
            totalUsers++;

            int eggs = (int)(user.Value["eggs"] ?? 0);
            int d20 = (int)(user.Value["d20Tokens"] ?? 0);
            int rrt = (int)(user.Value["rrTokens"] ?? 0);

            totalEggs += eggs;
            totalD20Tokens += d20;
            totalRRTokens += rrt;

            if (eggs > maxEggs) maxEggs = eggs;
            if (eggs < minEggs) minEggs = eggs;
        }

        int avgEggs = totalUsers > 0 ? totalEggs / totalUsers : 0;
        if (minEggs == int.MaxValue) minEggs = 0;

        // Calculate egg value in tokens (eggs locked in token purchases)
        int eggsInD20 = totalD20Tokens * 100;
        int eggsInRRT = totalRRTokens * 50;
        int totalEggValue = totalEggs + eggsInD20 + eggsInRRT;

        // Build message
        string message = $"📊 Economy Stats: {totalUsers} users | Total Eggs: {totalEggs} 🥚 | ";
        message += $"D20 Tokens: {totalD20Tokens} 🎲 | RRTokens: {totalRRTokens} 🎰 | ";
        message += $"Avg Eggs: {avgEggs} | Max: {maxEggs} | Min: {minEggs} | ";
        message += $"Total Value: {totalEggValue} eggs equivalent";

        CPH.SendMessage(message);

        return true;
    }
}
